mapper.select:
select 
count(1)
from BOK_BATCH_MARKETWARNING_INFO 
       where 1=1 

     AND BATCH_EXE_SEQ_NO = #{seqNo}


     AND YES_OR_NO = #{isWarn}


     AND TASK_ID = #{taskId}

select SEQ_NO as seqNo, BATCH_EXE_SEQ_NO as batchExeSeqNo, TASK_ID as taskId, BOOKSET_ID as booksetId, to_char(HAPPEN_DATE,'yyyy-mm-dd')as happenDate, to_char(BOOKSET_DATE,'yyyy-mm-dd') as booksetDate, to_char(BOOK_DATE,'yyyy-mm-dd') as bookDate, FINPROD_ID as finprodId, FINPROD_TYPE as finprodType, MARKET_CODE as marketCode, INV_AIM as invAim, VALUE_SOURCE as valueSource, to_char(THE_VALUE_DATE,'yyyy-mm-dd') as theValueDate, to_char(ACT_VALUE_DATE,'yyyy-mm-dd') as actValueDate, ACT_MARKET_PRICE as actMarketPrice from BOK_BATCH_MARKETWARNING_INFO where 1=1
AND BATCH_EXE_SEQ_NO = #{batchExedetailSeqNo}
AND TASK_ID = #{taskId}
